// Nettoyer et parser la réponse JSON de l'IA
let raw = $input.first().json.output || '';

// Supprimer les balises markdown ```json ... ```
raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  // Si l'IA n'a pas retourné de JSON valide, on construit une réponse de secours
  parsed = {
    chat_response: raw || "Désolé, je n'ai pas pu traiter votre demande. Pouvez-vous reformuler ?",
    intent: 'unknown',
    cert_id: null,
    suggestions: ['🔍 Vérifier un certificat', '❓ Aide', '📊 Statistiques']
  };
}

return [{
  json: {
    message:     parsed.chat_response || 'Réponse non disponible.',
    intent:      parsed.intent || 'unknown',
    cert_id:     parsed.cert_id || null,
    suggestions: parsed.suggestions || [],
    timestamp:   new Date().toISOString()
  }
}];
